import React, { useState } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [tasks, setTasks] = useState([]);
  const [newTaskName, setNewTaskName] = useState("");
  const [newTaskDesc, setNewTaskDesc] = useState("");
  const [editingTaskId, setEditingTaskId] = useState(null);
  const [editName, setEditName] = useState("");
  const [editDesc, setEditDesc] = useState("");

  const addTask = () => {
    if (!newTaskName.trim()) return;
    const newTask = {
      id: Date.now(),
      name: newTaskName,
      description: newTaskDesc,
      completed: false
    };
    setTasks([...tasks, newTask]);
    setNewTaskName("");
    setNewTaskDesc("");
  };

  const completeTask = (id) => {
    setTasks(tasks.map(task =>
      task.id === id ? { ...task, completed: true } : task
    ));
  };

  const startEdit = (task) => {
    setEditingTaskId(task.id);
    setEditName(task.name);
    setEditDesc(task.description);
  };

  const saveEdit = (id) => {
    setTasks(tasks.map(task =>
      task.id === id ? { ...task, name: editName, description: editDesc } : task
    ));
    setEditingTaskId(null);
    setEditName("");
    setEditDesc("");
  };

  // Productivity score
  const totalTasks = tasks.length;
  const completedTasks = tasks.filter(task => task.completed).length;
  const productivityScore = totalTasks > 0 
    ? Math.round((completedTasks / totalTasks) * 100) 
    : 0;

  return (
    <div className="dashboard-container">
      <h1 className="dashboard-title">Welcome to Nityo Dashboard</h1>

      {/* Add Task */}
      <div className="dashboard-card">
        <div className="emoji">✏️</div>
        <h3>Add Task</h3>
        <input
          type="text"
          placeholder="Task Name"
          value={newTaskName}
          onChange={(e) => setNewTaskName(e.target.value)}
        />
        <input
          type="text"
          placeholder="Task Description"
          value={newTaskDesc}
          onChange={(e) => setNewTaskDesc(e.target.value)}
        />
        <button className="action-btn" onClick={addTask}>Add Task</button>
      </div>

      {/* Task List */}
      <div className="dashboard-card">
        <div className="emoji">✅</div>
        <h3>Tasks</h3>
        {tasks.length > 0 ? (
          tasks.map(task => (
            <div key={task.id} className="task-item">
              {editingTaskId === task.id ? (
                <>
                  <input
                    type="text"
                    value={editName}
                    onChange={(e) => setEditName(e.target.value)}
                  />
                  <input
                    type="text"
                    value={editDesc}
                    onChange={(e) => setEditDesc(e.target.value)}
                  />
                  <button className="action-btn" onClick={() => saveEdit(task.id)}>Save</button>
                </>
              ) : (
                <>
                  <span style={{ textDecoration: task.completed ? "line-through" : "none" }}>
                    <strong>{task.name}</strong> — {task.description}
                  </span>
                  {!task.completed && (
                    <button className="action-btn" onClick={() => completeTask(task.id)}>
                      Complete
                    </button>
                  )}
                  <button className="action-btn" onClick={() => startEdit(task)}>Edit</button>
                </>
              )}
            </div>
          ))
        ) : (
          <p>No tasks yet</p>
        )}
      </div>

      {/* Reports */}
      <div className="dashboard-card">
        <div className="emoji">📊</div>
        <h3>Reports</h3>
        <p>Total Tasks: {totalTasks}</p>
        <p>Completed: {completedTasks}</p>
        <p>Productivity Score: {productivityScore}%</p>
        <div className="progress-bar">
          <div 
            className="progress-fill" 
            style={{ width: `${productivityScore}%` }}
          ></div>
        </div>
      </div>

      {/* Events */}
      <div className="dashboard-card">
        <div className="emoji">📅</div>
        <button className="action-btn">Manage Events</button>
      </div>

      {/* Theme Toggle */}
      <div className="dashboard-card">
        <div className="emoji">🌙☀️</div>
        <button
          className="action-btn"
          onClick={() => document.body.classList.toggle("dark-mode")}
        >
          Toggle Theme
        </button>
      </div>
    </div>
  );
}

export default Dashboard;
